package com.luminor.tavernquest.data.local.database.dao
import androidx.room.*; import com.luminor.tavernquest.data.local.database.entity.DailyContractEntity; import com.luminor.tavernquest.data.local.database.relation.DailyContractWithTemplate; import kotlinx.coroutines.flow.Flow
@Dao interface DailyContractDao{@Insert(onConflict=OnConflictStrategy.IGNORE) suspend fun insertAll(v:List<DailyContractEntity>);@Transaction @Query("SELECT * FROM daily_contract WHERE date=:date ORDER BY id") suspend fun getByDate(date:String):List<DailyContractWithTemplate>;@Transaction @Query("SELECT * FROM daily_contract WHERE id=:id LIMIT 1") suspend fun getById(id:String):DailyContractWithTemplate?;@Transaction @Query("SELECT * FROM daily_contract WHERE date=:date ORDER BY id") fun observeByDate(date:String):Flow<List<DailyContractWithTemplate>>;@Query("SELECT COUNT(*) FROM daily_contract WHERE date=:date AND status='ACCEPTED'") suspend fun countAcceptedByDate(date:String):Int;@Query("UPDATE daily_contract SET status=:status, acceptedAt=:acceptedAt, completedAt=:completedAt WHERE id=:id") suspend fun updateStatus(id:String,status:String,acceptedAt:Long?,completedAt:Long?);@Query("UPDATE daily_contract SET status='EXPIRED' WHERE date<:date AND status IN ('AVAILABLE','ACCEPTED')") suspend fun expireBefore(date:String);@Query("DELETE FROM daily_contract") suspend fun deleteAll()}
